-- Import only into a NEW dedicated MySQL 8 database.
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('superadmin','admin','user') NOT NULL DEFAULT 'user',status ENUM('active','suspended','pending') NOT NULL DEFAULT 'active',last_login_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX idx_user_role(role,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE transcripts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,source_type ENUM('url','upload') NOT NULL,platform VARCHAR(32) NOT NULL,source_url VARCHAR(2048) NULL,source_file VARCHAR(500) NULL,original_filename VARCHAR(255) NULL,title VARCHAR(500) NULL,language VARCHAR(20) NOT NULL DEFAULT 'auto',duration_seconds INT UNSIGNED NULL,transcript_text LONGTEXT NULL,provider_payload JSON NULL,provider_name VARCHAR(60) NULL,provider_model VARCHAR(120) NULL,status ENUM('queued','processing','completed','failed') NOT NULL DEFAULT 'queued',error_message TEXT NULL,completed_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,CONSTRAINT fk_transcript_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_transcript_user_created(user_id,created_at),INDEX idx_transcript_user_status(user_id,status),FULLTEXT KEY ft_transcript(title,transcript_text)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE transcript_segments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,transcript_id BIGINT UNSIGNED NOT NULL,sequence_no INT UNSIGNED NOT NULL,start_seconds DECIMAL(12,3) NOT NULL DEFAULT 0,end_seconds DECIMAL(12,3) NOT NULL DEFAULT 0,content TEXT NOT NULL,CONSTRAINT fk_segment_transcript FOREIGN KEY(transcript_id) REFERENCES transcripts(id) ON DELETE CASCADE,UNIQUE KEY uq_segment(transcript_id,sequence_no),INDEX idx_segment_time(transcript_id,start_seconds)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE jobs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,transcript_id BIGINT UNSIGNED NOT NULL,job_type VARCHAR(40) NOT NULL,payload JSON NOT NULL,status ENUM('queued','processing','completed','failed') NOT NULL DEFAULT 'queued',attempts TINYINT UNSIGNED NOT NULL DEFAULT 0,available_at DATETIME NOT NULL,started_at DATETIME NULL,finished_at DATETIME NULL,error_message TEXT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,CONSTRAINT fk_job_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_job_transcript FOREIGN KEY(transcript_id) REFERENCES transcripts(id) ON DELETE CASCADE,INDEX idx_job_queue(status,available_at,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE usage_ledger(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,transcript_id BIGINT UNSIGNED NULL,units DECIMAL(12,3) NOT NULL,reason VARCHAR(160) NOT NULL,created_at DATETIME NOT NULL,CONSTRAINT fk_usage_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_usage_transcript FOREIGN KEY(transcript_id) REFERENCES transcripts(id) ON DELETE SET NULL,INDEX idx_usage_user(user_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE ai_outputs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,transcript_id BIGINT UNSIGNED NOT NULL,task VARCHAR(40) NOT NULL,output_text LONGTEXT NOT NULL,created_at DATETIME NOT NULL,CONSTRAINT fk_ai_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_ai_transcript FOREIGN KEY(transcript_id) REFERENCES transcripts(id) ON DELETE CASCADE,INDEX idx_ai_user(user_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE provider_runs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,transcript_id BIGINT UNSIGNED NOT NULL,provider_name VARCHAR(60) NOT NULL,model_name VARCHAR(120) NULL,audio_seconds INT UNSIGNED NULL,cost_usd DECIMAL(14,8) NULL,processing_ms INT UNSIGNED NOT NULL DEFAULT 0,status ENUM('completed','failed') NOT NULL,error_message TEXT NULL,created_at DATETIME NOT NULL,CONSTRAINT fk_provider_run_transcript FOREIGN KEY(transcript_id) REFERENCES transcripts(id) ON DELETE CASCADE,INDEX idx_provider_run_transcript(transcript_id),INDEX idx_provider_run_provider(provider_name,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
